// 한 증상의 두 원인 사례를 같은 화면 규격으로 작성하기 위한 데이터 생성 함수입니다.
// measured: 고장 시 계측값, recovery: 복구 재시험에서 확인할 항목입니다.
function trainingCase(
  id,
  name,
  system,
  part,
  summary,
  checks,
  causes,
  actions,
  variants,
  measured,
  recovery,
) {
  // id로 가상 알람 코드를 만들고, 두 변형의 원인·조치 번호를 배열 순서와 연결합니다.
  return {
    id,
    code: `SIM-${id.toUpperCase()}`,
    name,
    system,
    part,
    summary,
    symptom: `${summary} 훈련 장비는 HOLD 상태이며 후속 처리 진행을 보류합니다.`,
    checks,
    causes,
    actions,
    // 각 변형은 [세 점검 결과, 비정상 결과 번호, 복구 후 해설]로 입력합니다.
    variants: variants.map((v, i) => ({
      cause: i,
      action: i,
      results: v[0],
      bad: v[1],
      lesson: v[2],
    })),
    measured,
    recovery,
  };
}

